//! 🫳️ Neutral owned UTF-8/octet reconstruction, interior cancellation and cumulative admission.
use super::{reconstruct_blob,reconstruct_text,Reconstruction};
use super::super::{export_sqlite_database,SqliteDatabase,SqliteDatabaseLimits,SqliteRow,SqliteSnapshotControl as Control,SqliteSnapshotPhase as Phase,SqliteSnapshotProgress,SqliteValue};
fn plan()->serde_json::Value{serde_json::from_str(include_str!("../../🧫️fixtures/🫳️reconstruction/🔣️.json")).unwrap()}
fn payloads(plan:&serde_json::Value)->(String,Vec<u8>){(plan["textUnit"].as_str().unwrap().repeat(plan["textRepeats"].as_u64().unwrap()as usize),plan["blobUnit"].as_array().unwrap().iter().map(|value|value.as_u64().unwrap()as u8).collect::<Vec<_>>().repeat(plan["blobRepeats"].as_u64().unwrap()as usize))}
#[test]
fn reconstruction_owned_copy_cancels_inside_utf8_and_octets(){
 let plan=plan();let(text,blob)=payloads(&plan);
 for bytes in [false,true]{let total=if bytes{blob.len()}else{text.len()};let mut interior=None;let mut callback=|event:SqliteSnapshotProgress|if event.phase==Phase::ReconstructSnapshot&&event.total==total&&event.completed>=plan["cancelAfter"].as_u64().unwrap()as usize&&event.completed<total{interior=Some(event.completed);false}else{true};let mut control=Control::new(&mut callback,SqliteDatabaseLimits::default());let result=if bytes{reconstruct_blob(&mut control,&blob).map(|value|value.len())}else{reconstruct_text(&mut control,&text).map(|value|value.len())};assert!(result.is_err(),"copy must stop inside the selected native field");assert_eq!(control.ledger.reconstruction_bytes,total,"reserved ownership remains charged after interior cancellation");drop(control);assert!(interior.is_some());}
}
#[test]
fn reconstruction_owned_copy_preserves_exact_budget_and_before_copy_refusal(){
 let plan=plan();let(text,blob)=payloads(&plan);let maximum=plan["combinedBytes"].as_u64().unwrap()as usize;assert_eq!(text.len(),plan["textBytes"].as_u64().unwrap()as usize);assert_eq!(blob.len(),plan["blobBytes"].as_u64().unwrap()as usize);
 let limits=SqliteDatabaseLimits{max_value_bytes:maximum,..Default::default()};let mut accept=|_|true;let mut control=Control::new(&mut accept,limits);assert_eq!(reconstruct_text(&mut control,&text).unwrap(),text);assert_eq!(reconstruct_blob(&mut control,&blob).unwrap(),blob);assert_eq!(control.ledger.reconstruction_bytes,maximum);
 let mut accept=|_|true;let mut control=Control::new(&mut accept,SqliteDatabaseLimits{max_value_bytes:maximum-1,..limits});assert_eq!(reconstruct_text(&mut control,&text).unwrap(),text);assert!(reconstruct_blob(&mut control,&blob).is_err());assert_eq!(control.ledger.reconstruction_bytes,text.len());assert_eq!(control.ledger.reconstruction_units,1);
 let mut callback=|event:SqliteSnapshotProgress|event.total!=0||event.completed==0;let mut control=Control::new(&mut callback,limits);let mut owner=Reconstruction::new(&mut control).unwrap();assert!(owner.blob(&blob).is_err());drop(owner);assert_eq!(control.ledger.reconstruction_bytes,0);assert_eq!(control.ledger.reconstruction_units,0);
}
#[test]
fn reconstruction_owned_copy_independent_sqlite_utf8_and_blob_oracle(){
 let plan=plan();let(text,blob)=payloads(&plan);let mut accept=|_|true;let mut control=Control::new(&mut accept,SqliteDatabaseLimits{max_value_bytes:plan["combinedBytes"].as_u64().unwrap()as usize,..Default::default()});let mut database=SqliteDatabase::from_schema("CREATE TABLE restored_native_field(id INTEGER PRIMARY KEY,text_value TEXT NOT NULL,blob_value BLOB NOT NULL)").unwrap();database.table_mut("restored_native_field").unwrap().rows.push(SqliteRow{rowid:1,values:vec![SqliteValue::Integer(1),SqliteValue::Text(reconstruct_text(&mut control,&text).unwrap()),SqliteValue::Blob(reconstruct_blob(&mut control,&blob).unwrap())]});
 let bytes=export_sqlite_database(&database,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let input=serde_json::json!({"plan":plan});
 let script=r#"import{Database}from'bun:sqlite';const input=JSON.parse(process.argv[1]);const db=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));const row=db.query('SELECT text_value,blob_value,length(CAST(text_value AS BLOB)) AS textBytes,length(blob_value) AS blobBytes FROM restored_native_field').get();if(row.text_value!==input.plan.textUnit.repeat(input.plan.textRepeats)||row.textBytes!==input.plan.textBytes||row.blobBytes!==input.plan.blobBytes)throw Error('owned fields');for(let index=0;index<row.blob_value.length;index++)if(row.blob_value[index]!==input.plan.blobUnit[index%input.plan.blobUnit.length])throw Error('octet');console.log('independent reconstruction oracle');"#;
 use std::{io::Write,process::{Command,Stdio}};let mut child=Command::new("bun").args(["-e",script,&input.to_string()]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));assert!(String::from_utf8_lossy(&output.stdout).contains("independent reconstruction oracle"));
}
